from __future__ import annotations

import math
from typing import Any, Dict, Optional

from fastapi import Header, HTTPException, Request

from .config import ConfigHolder
from .oidc import verify_oidc
from .ratelimit import _bucket


def maintenance_guard(cfg: ConfigHolder):
    def dep() -> None:
        maintenance_cfg = getattr(cfg.current, "maintenance", None)
        if isinstance(maintenance_cfg, dict) and maintenance_cfg.get("enabled"):
            message = maintenance_cfg.get("message", "Service under maintenance")
            raise HTTPException(
                status_code=503,
                detail={"code": "maintenance", "message": message},
            )

    return dep


def stepup_guard(cfg: ConfigHolder):
    def dep(x_step_up_token: str = Header(default="")) -> None:
        step_cfg = getattr(cfg.current, "stepup", None) or getattr(cfg.current, "step_up", None)
        if not isinstance(step_cfg, dict):
            return
        if not step_cfg.get("required"):
            return
        expected = step_cfg.get("token")
        if not expected or x_step_up_token != expected:
            raise HTTPException(
                status_code=403,
                detail={"code": "step_up_required", "message": "Missing or invalid step-up token"},
            )

    return dep


def oidc_guard(cfg: ConfigHolder):
    def dep(
        request: Request,
        authorization: str = Header(default=""),
        x_audience: str = Header(default=""),
    ) -> Dict[str, Any]:
        if not authorization.startswith("Bearer "):
            raise HTTPException(
                status_code=401,
                detail={"code": "unauthorized", "message": "Missing Bearer token"},
            )
        id_token = authorization.split(" ", 1)[1]
        try:
            claims = verify_oidc(cfg, id_token, audience=x_audience or None)
            request.state.oidc_claims = claims
            return claims
        except Exception as exc:  # pragma: no cover - fastapi converts to 401
            raise HTTPException(
                status_code=401,
                detail={"code": "unauthorized", "message": str(exc)},
            ) from exc

    return dep


def rate_limit_guard(cfg: ConfigHolder, per_endpoint: bool = True):
    async def dep(request: Request) -> None:
        rate_cfg = getattr(cfg.current, "rate_limits", {}) or {}

        global_rpm = int(rate_cfg.get("global_per_minute", 0))
        if global_rpm:
            global_burst = int(rate_cfg.get("global_burst", global_rpm))
            ok, retry_after = await _bucket("__global__", global_rpm, global_burst).take(1)
            if not ok:
                headers = {"Retry-After": str(max(1, math.ceil(retry_after)))}
                raise HTTPException(
                    status_code=429,
                    detail={"code": "rate_limited", "message": "Too many requests"},
                    headers=headers,
                )

        claims = getattr(request.state, "oidc_claims", None)
        caller: Optional[str] = None
        if isinstance(claims, dict):
            caller = claims.get("sub")
        if not caller:
            caller = request.headers.get("X-Caller")
        if not caller and request.client:
            caller = request.client.host
        caller = caller or "anonymous"

        route = request.scope.get("route")
        path = getattr(route, "path", request.url.path)
        method = request.method
        endpoint_key = f"{method} {path}"

        endpoint_limits = {}
        endpoints_cfg = rate_cfg.get("endpoints", {}) or {}
        if endpoint_key in endpoints_cfg:
            endpoint_limits = endpoints_cfg[endpoint_key]

        default_rpm = int(rate_cfg.get("per_caller_per_minute", 60))
        rpm = int(endpoint_limits.get("per_minute", default_rpm))
        burst_default = endpoint_limits.get("per_minute", default_rpm)
        burst = int(endpoint_limits.get("burst", burst_default))

        key = caller
        if per_endpoint:
            key = f"{caller}|{endpoint_key}"

        ok, retry_after = await _bucket(key, rpm, burst).take(1)
        if not ok:
            headers = {"Retry-After": str(max(1, math.ceil(retry_after)))}
            raise HTTPException(
                status_code=429,
                detail={"code": "rate_limited", "message": "Too many requests"},
                headers=headers,
            )

    return dep

"""Scenario endpoints for profitability modelling."""

from __future__ import annotations

from datetime import datetime
from typing import Dict
from uuid import uuid4

from fastapi import APIRouter, HTTPException, status

from ...schemas import ScenarioCreate, ScenarioDetail, ScenarioListItem

router = APIRouter()


class _ScenarioStore:
    """A lightweight, in-memory store used until the database layer ships."""

    def __init__(self) -> None:
        self._items: Dict[str, ScenarioDetail] = {}

    def list(self) -> list[ScenarioListItem]:
        return [
            ScenarioListItem(
                id=item.id,
                name=item.name,
                created_at=item.created_at,
                updated_at=item.updated_at,
            )
            for item in self._items.values()
        ]

    def get(self, scenario_id: str) -> ScenarioDetail:
        try:
            return self._items[scenario_id]
        except KeyError as exc:  # pragma: no cover - defensive branch
            raise HTTPException(status_code=status.HTTP_404_NOT_FOUND) from exc

    def create(self, payload: ScenarioCreate) -> ScenarioDetail:
        scenario_id = str(uuid4())
        now = datetime.utcnow()
        detail = ScenarioDetail(
            id=scenario_id,
            name=payload.name,
            params=payload.params,
            notes=[],
            created_at=now,
            updated_at=now,
        )
        self._items[scenario_id] = detail
        return detail


_store = _ScenarioStore()


@router.get("", response_model=list[ScenarioListItem])
async def list_scenarios() -> list[ScenarioListItem]:
    """Return saved scenarios for the active organisation."""

    return _store.list()


@router.post("", response_model=ScenarioDetail, status_code=status.HTTP_201_CREATED)
async def create_scenario(payload: ScenarioCreate) -> ScenarioDetail:
    """Create a new scenario in the temporary in-memory store."""

    return _store.create(payload)


@router.get("/{scenario_id}", response_model=ScenarioDetail)
async def get_scenario(scenario_id: str) -> ScenarioDetail:
    """Return a single scenario by identifier."""

    return _store.get(scenario_id)

"""Configuration primitives for the mining-ops lab service."""

from functools import lru_cache
from typing import List

from pydantic import Field, HttpUrl, field_validator
from pydantic_settings import BaseSettings, SettingsConfigDict


class AppSettings(BaseSettings):
    """Runtime configuration loaded from environment variables."""

    database_url: str = Field(
        "postgresql+asyncpg://postgres:postgres@localhost:5432/mining_ops_lab",
        description="Async SQLAlchemy connection string.",
    )
    redis_url: str = Field("redis://localhost:6379/0", description="Redis connection URI.")
    stripe_api_key: str = Field("", description="Stripe secret key for billing integration.")
    jwt_secret_key: str = Field(..., description="Secret used to sign JWT access tokens.")
    jwt_refresh_secret_key: str = Field(..., description="Secret used to sign refresh tokens.")
    telemetry_bucket_span_seconds: int = Field(
        10, description="Telemetry sampling window used by the sidecar agent."
    )
    allowed_image_regexes: List[str] = Field(
        default_factory=lambda: [
            r"^([a-z0-9]+[._-]?)+/(?:[a-z0-9._-]+)(?::[a-zA-Z0-9._-]+)?$",
            r"^(?:ghcr\.io|public\.ecr\.aws)/[\w][\w./-]*(?::[\w.-]+)?$",
        ],
        description="Regex allowlist applied to user-supplied container image URIs.",
    )
    max_runtime_minutes: int = Field(
        120, description="Absolute upper bound on job runtime enforced by the API."
    )
    minimum_budget_cap_usd: float = Field(0.5, description="Minimum allowed budget for a job.")
    enable_monte_carlo: bool = Field(True, description="Toggle Monte Carlo profitability modeling.")
    docs_url: HttpUrl | None = Field(
        None,
        description="Optional override for OpenAPI documentation host (useful behind proxies).",
    )

    model_config = SettingsConfigDict(env_prefix="MOL_", case_sensitive=False)

    @field_validator("allowed_image_regexes")
    @classmethod
    def _strip_empty(cls, values: List[str]) -> List[str]:
        return [value for value in values if value]


@lru_cache
def get_settings() -> AppSettings:
    """Return a cached instance of :class:`AppSettings`."""

    return AppSettings()
